function encode(command) {
  var LIMIT = 0.1;
  if (Array.isArray(command)) {
    if (command.length !== 2) {
      throw new Error("step command requires exactly 2 channels");
    }
    for (var i = 0; i < 2; i++) {
      var v = command[i];
      if (typeof v !== "number" || !isFinite(v) || v < -LIMIT || v > LIMIT) {
        throw new Error("channel value out of range [-0.1,0.1]");
      }
    }
    return JSON.stringify({ op: "step", channels: [command[0], command[1]] }) + "\n";
  }
  if (command && typeof command === "object") {
    if (command.op === "lift") {
      if (command.position !== "up" && command.position !== "down") {
        throw new Error("lift position must be up or down");
      }
      return JSON.stringify({ op: "lift", position: command.position }) + "\n";
    }
    if (command.op === "grip") {
      if (command.state !== "open" && command.state !== "closed") {
        throw new Error("grip state must be open or closed");
      }
      return JSON.stringify({ op: "grip", state: command.state }) + "\n";
    }
  }
  throw new Error("unsupported command");
}

function decode(rawReply) {
  if (typeof rawReply !== "string") {
    throw new Error("reply must be a string");
  }
  if (rawReply.length === 0 || rawReply.charAt(rawReply.length - 1) !== "\n") {
    throw new Error("reply frame must end with LF");
  }
  var text = rawReply.slice(0, rawReply.length - 1);
  if (text.indexOf("\n") !== -1) {
    throw new Error("reply must be exactly one JSON line");
  }
  var reply = JSON.parse(text);
  if (!reply || typeof reply !== "object" || Array.isArray(reply)) {
    throw new Error("reply is not an object");
  }
  if (reply.ok !== true) {
    throw new Error("device error: " + (reply.error !== undefined ? String(reply.error) : "ok:false"));
  }
  if (reply.limited !== undefined && typeof reply.limited !== "boolean") {
    throw new Error("limited field must be boolean");
  }
  var accepted = reply.accepted;
  if (Array.isArray(accepted)) {
    if (accepted.length !== 2) {
      throw new Error("step reply must have 2 channels");
    }
    for (var i = 0; i < 2; i++) {
      if (typeof accepted[i] !== "number" || !isFinite(accepted[i]) || accepted[i] < -0.1 || accepted[i] > 0.1) {
        throw new Error("step reply channel not numeric or out of range");
      }
    }
  } else if (accepted && typeof accepted === "object") {
    if (accepted.op === "lift") {
      if (accepted.position !== "up" && accepted.position !== "down") {
        throw new Error("invalid lift reply position");
      }
    } else if (accepted.op === "grip") {
      if (accepted.state !== "open" && accepted.state !== "closed") {
        throw new Error("invalid grip reply state");
      }
    } else {
      throw new Error("unknown accepted object");
    }
  } else {
    throw new Error("missing accepted field");
  }
  return { applied: accepted, limited: reply.limited === true };
}

