function control(state) {
  var tip = state.tip;
  var target = state.target;
  if (!tip || !target || tip.length !== 2 || target.length !== 2) {
    return { action: "stop", reason: "missing tip or target" };
  }
  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  if (!isFinite(ex) || !isFinite(ey)) {
    return { action: "stop", reason: "non-finite error" };
  }
  var e = Math.sqrt(ex * ex + ey * ey);
  if (e <= state.tolerancePx) {
    return { action: "verify" };
  }
  var H = state.history || [];
  var S = [[0, 0], [0, 0]];
  var D = [[0, 0], [0, 0]];
  var n = 0;
  for (var t = 0; t < H.length; t++) {
    var h = H[t];
    if (!h || !h.applied || !h.delta) continue;
    var c = h.applied;
    var d = h.delta;
    if (c.length !== 2 || d.length !== 2) continue;
    if (!isFinite(c[0]) || !isFinite(c[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    for (var i = 0; i < 2; i++) {
      for (var j = 0; j < 2; j++) {
        S[i][j] += c[i] * c[j];
      }
    }
    for (var k = 0; k < 2; k++) {
      for (var m = 0; m < 2; m++) {
        D[k][m] += d[k] * c[m];
      }
    }
    n++;
  }
  var detS = S[0][0] * S[1][1] - S[0][1] * S[1][0];
  var scaleS = S[0][0] + S[1][1];
  var wellConditioned = n >= 3 && scaleS > 1e-8 && detS > 0.02 * scaleS * scaleS;
  if (!wellConditioned) {
    // cycle through four probe directions (both signs) so boundary-limited channels still get excited
    var probes = [[0.05, 0], [0, 0.05], [-0.05, 0], [0, -0.05]];
    var idx = H.length % 4;
    return { action: "move", u: probes[idx] };
  }
  var lam = 1e-9 * scaleS;
  var Sr = [[S[0][0] + lam, S[0][1]], [S[1][0], S[1][1] + lam]];
  var detR = Sr[0][0] * Sr[1][1] - Sr[0][1] * Sr[1][0];
  var Sinv = [[Sr[1][1] / detR, -Sr[0][1] / detR], [-Sr[1][0] / detR, Sr[0][0] / detR]];
  var J = [[0, 0], [0, 0]];
  for (var a = 0; a < 2; a++) {
    for (var b = 0; b < 2; b++) {
      J[a][b] = D[a][0] * Sinv[0][b] + D[a][1] * Sinv[1][b];
    }
  }
  var detJ = J[0][0] * J[1][1] - J[0][1] * J[1][0];
  if (!isFinite(detJ) || Math.abs(detJ) < 1e-6) {
    var pr = [[0.05, 0], [0, 0.05], [-0.05, 0], [0, -0.05]];
    return { action: "move", u: pr[H.length % 4] };
  }
  var c0 = (J[1][1] * ex - J[0][1] * ey) / detJ;
  var c1 = (-J[1][0] * ex + J[0][0] * ey) / detJ;
  if (!isFinite(c0) || !isFinite(c1)) {
    return { action: "stop", reason: "singular mapping" };
  }
  var mx = Math.max(Math.abs(c0), Math.abs(c1));
  if (mx > 0.05) {
    c0 = c0 * 0.05 / mx;
    c1 = c1 * 0.05 / mx;
  } else if (mx > 0 && mx < 0.01) {
    c0 = c0 * 0.01 / mx;
    c1 = c1 * 0.01 / mx;
  }
  c0 = Math.max(-0.1, Math.min(0.1, c0));
  c1 = Math.max(-0.1, Math.min(0.1, c1));
  return { action: "move", u: [c0, c1] };
}
